/** Public IDs/factories, actual Survival use/harvest, Source recipes and separate-process owners. */
@EventBusSubscriber(modid="vandorlabs")
public final class GlassCanonicalChecks {
 private static final BlockPos BASE=new BlockPos(8600,100,8600);private static int checks,ticks;private static boolean reading;private static BlockPos tracked;private static final List<ItemStack> drops=new ArrayList<>();
 private static void need(boolean yes,String text){checks++;if(!yes)throw new AssertionError("Canonical Glass "+text);}
 private static ResourceLocation id(String name){return ResourceLocation.parse("vandorlabs:"+name);}
 private static NativeGlassBlock block(){var value=BuiltInRegistries.BLOCK.get(id("programmable_glass"));need(value instanceof NativeGlassBlock,"actual public block installed");return (NativeGlassBlock)value;}
 private static NativeGlassItem item(){var value=BuiltInRegistries.ITEM.get(id("programmable_glass"));need(value instanceof NativeGlassItem,"actual public item installed");return (NativeGlassItem)value;}
 private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {private int window=800;Actor(ServerLevel w){super(w,new com.mojang.authlib.GameProfile(UUID.fromString("b8826df1-2233-4f53-ae6e-8e2035fa79d8"),"CanonicalGlass"));getInventory().selected=0;setGameMode(GameType.SURVIVAL);}
  @Override public OptionalInt openMenu(net.minecraft.world.MenuProvider provider,java.util.function.Consumer<net.minecraft.network.RegistryFriendlyByteBuf> writer){containerMenu=provider.createMenu(++window,getInventory(),this);var bytes=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),serverLevel().registryAccess());try{writer.accept(bytes);need(containerMenu instanceof NativeGlassMenu menu&&bytes.readBlockPos().equals(menu.tile.getBlockPos())&&!bytes.isReadable(),"canonical dedicated menu opening data");}finally{bytes.release();}return OptionalInt.of(window);}
 }
 private static ItemStack configured(){var result=new ItemStack(item(),2);var choices=new CompoundTag();choices.putInt("Size",1);choices.putInt("Shade",5);choices.putInt("Tint",2);choices.putInt("Material",64);choices.putInt("LayoutMode",1);choices.putBoolean("Framed",true);choices.putBoolean("Join",false);var generic=new CompoundTag();generic.putString("FutureGlass","CANONICAL_PRIVATE");var persistent=new CompoundTag();persistent.putString("Owner","prepared:private");generic.put("NeoForgeData",persistent);var root=new CompoundTag();root.put(NativeGlassItem.CONFIGURATION,choices);root.put(NativeGlassItem.GENERIC,generic);result.set(DataComponents.CUSTOM_DATA,CustomData.of(root));return result;}
 private static NativeGlassEntity place(ServerLevel w,Actor actor,BlockPos pos,int yaw,double hit){w.getChunkAt(pos);w.setBlock(pos.below(),Blocks.STONE.defaultBlockState(),18);w.setBlock(pos,Blocks.AIR.defaultBlockState(),18);actor.setPos(pos.getX()+.5,pos.getY(),pos.getZ()-2);actor.setYRot(Direction.from2DDataValue(yaw).toYRot());actor.setShiftKeyDown(false);var stack=configured();actor.setItemInHand(InteractionHand.MAIN_HAND,stack);var click=new BlockHitResult(new Vec3(pos.getX()+hit,pos.getY(),pos.getZ()+hit),Direction.UP,pos.below(),false);need(actor.gameMode.useItemOn(actor,w,stack,InteractionHand.MAIN_HAND,click).consumesAction()&&stack.getCount()==1,"real Survival public configured placement consumes one");var owner=(NativeGlassEntity)w.getBlockEntity(pos);need(owner!=null&&owner.getType()==BuiltInRegistries.BLOCK_ENTITY_TYPE.get(id("programmable_glass"))&&!owner.inert(),"exact canonical Source BE factory");owner.refreshFluidGeometry();need(owner.settings().glass().shade==5&&owner.settings().glass().material==64&&!owner.settings().glass().join,"public item settings installed");var pick=block().getCloneItemStack(owner.getBlockState(),new BlockHitResult(Vec3.atCenterOf(pos),Direction.NORTH,pos,false),w,pos,actor);need(pick.is(item())&&NativeGlassItem.configuration(pick).getInt("Shade")==5&&!pick.has(DataComponents.BLOCK_ENTITY_DATA)&&!pick.toString().contains("CANONICAL_PRIVATE"),"configured public pick has settings only");return owner;}
 private static void recipes(ServerLevel w){var cells=new ArrayList<ItemStack>();for(int i=0;i<9;i++)cells.add(new ItemStack(i==4?VandorLabsBootstrap.MATTER_INGOT.get():Items.GLASS));var input=CraftingInput.of(3,3,cells);var recipe=(CraftingRecipe)w.getRecipeManager().byKey(id("programmable_glass")).orElseThrow().value();need(recipe.matches(input,w)&&recipe.assemble(input,w.registryAccess()).is(item())&&recipe.assemble(input,w.registryAccess()).getCount()==1,"Source8glass/matter recipe");var diagonal=(CraftingRecipe)w.getRecipeManager().byKey(id("programmable_diagonal_glass")).orElseThrow().value();var upgrade=CraftingInput.of(2,1,List.of(new ItemStack(item()),new ItemStack(VandorLabsBootstrap.ALLOY_INGOT.get())));need(diagonal.matches(upgrade,w)&&diagonal.assemble(upgrade,w.registryAccess()).is(VandorLabsBootstrap.PROGRAMMABLE_DIAGONAL_GLASS_ITEM.get()),"existing Source diagonal recipe activates with ordinary Glass");}
 @SubscribeEvent public static void joined(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent e){if(tracked!=null&&!e.isCanceled()&&e.getEntity() instanceof ItemEntity drop&&drop.position().distanceToSqr(Vec3.atCenterOf(tracked))<16)drops.add(drop.getItem().copy());}
 private static void mining(ServerLevel w,Actor actor){int cases=0;for(boolean inert:new boolean[]{false,true})for(int mode=0;mode<3;mode++){var pos=BASE.east(60+cases*4);actor.setGameMode(GameType.SURVIVAL);var owner=place(w,actor,pos,0,.5);CompoundTag original=null;if(inert){original=owner.saveWithoutMetadata(w.registryAccess());original.putInt("NativeGlassSchema",99);original.putByteArray("UnknownOwner",new byte[]{1,4,9,16});owner.loadWithComponents(original,w.registryAccess());need(owner.inert(),"future owner inert");}actor.setGameMode(mode==2?GameType.CREATIVE:GameType.SURVIVAL);actor.setItemInHand(InteractionHand.MAIN_HAND,mode==1?new ItemStack(Items.WOODEN_PICKAXE):ItemStack.EMPTY);tracked=pos;drops.clear();need(actor.gameMode.destroyBlock(pos)&&w.getBlockState(pos).isAir(),"actual public harvest");int count=drops.stream().filter(s->s.is(item())).mapToInt(ItemStack::getCount).sum();need(count==(inert||mode!=2?1:0),"exact Source normal/creative or sole recovery drop mode="+mode+" inert="+inert+" drops="+drops);if(count==1){var dropped=drops.stream().filter(s->s.is(item())).findFirst().orElseThrow();if(inert)need(NativeGlassItem.configuration(dropped).getCompound(NativeGlassEntity.RECOVERY).equals(original),"complete opaque sole recovery snapshot");else need(!dropped.has(DataComponents.CUSTOM_DATA)&&!dropped.has(DataComponents.BLOCK_ENTITY_DATA),"Source plain normal drop");}tracked=null;cases++;}need(cases==6,"hand/wood/creative valid+inert cases");}
 private static void saved(ServerLevel w){var owner=(NativeGlassEntity)w.getBlockEntity(BASE);need(owner!=null&&!owner.inert()&&owner.settings().glass().shade==5,"saved exact canonical owner");var tag=owner.saveWithFullMetadata(w.registryAccess());need(tag.getString("id").equals("vandorlabs:programmable_glass")&&tag.getString("FutureGlass").equals("CANONICAL_PRIVATE")&&tag.getCompound("NeoForgeData").getString("Owner").equals("canonical:live"),"Source BE identity and live/opaque fields survive");need(!owner.getUpdateTag(w.registryAccess()).toString().contains("CANONICAL_PRIVATE"),"public projection excludes private fields");var legacy=(NativeGlassEntity)w.getBlockEntity(BASE.east(8));need(legacy!=null&&legacy.settings().glass().size==1&&!legacy.settings().glass().legacySize,"absent listed size and old absent GlassSize resolve explicit default1");var recovery=(NativeGlassEntity)w.getBlockEntity(BASE.east(16));need(recovery!=null&&recovery.inert()&&recovery.recoverySnapshot().getInt("NativeGlassSchema")==99&&Arrays.equals(recovery.recoverySnapshot().getByteArray("UnknownOwner"),new byte[]{2,3,5,7}),"saved opaque recovery remains one inert owner");}
 @SubscribeEvent public static void started(net.neoforged.neoforge.event.server.ServerStartedEvent e){String phase=System.getProperty("vandorlabs.transmitterPhase","");if(!phase.startsWith("flat-glass-canonical-"))return;var server=e.getServer();System.out.println("[vandorlabs][glass-canonical] actual server PID="+ProcessHandle.current().pid());try{var w=server.overworld();var b=block();var plain=b.defaultBlockState();need(plain.getDestroySpeed(w,BASE)==.5F&&b.getExplosionResistance()==1.2F&&plain.getSoundType().getVolume()==1&&plain.getSoundType().getPitch()==1,"actual Source properties");need(!plain.requiresCorrectToolForDrops()&&!plain.is(net.minecraft.tags.BlockTags.MINEABLE_WITH_PICKAXE),"Source hand/wood rawspeed without invented pickaxe tag");recipes(w);for(int x:new int[]{0,8,16}){var p=BASE.east(x);w.setChunkForced(p.getX()>>4,p.getZ()>>4,true);w.getChunkAt(p);}if(phase.endsWith("read")){reading=true;return;}var actor=new Actor(w);int placements=0;for(int yaw=0;yaw<4;yaw++)for(double hit:new double[]{.1,.5,.9}){var pos=BASE.east(200+placements*3);var owner=place(w,actor,pos,yaw,hit);need(owner.getBlockState().getValue(NativeGlassBlock.ROTATED)==(Direction.from2DDataValue(yaw).getAxis()==Direction.Axis.X),"public original hit placement axis");w.removeBlock(pos,false);placements++;}need(placements==12,"all public axes/depth bands");mining(w,actor);actor.setGameMode(GameType.SURVIVAL);var owner=place(w,actor,BASE,0,.5);owner.getPersistentData().putString("Owner","canonical:live");actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(VandorLabsBootstrap.CONFIGURIZER.get()));actor.setShiftKeyDown(true);var hit=new BlockHitResult(Vec3.atCenterOf(BASE),Direction.NORTH,BASE,false);need(actor.getMainHandItem().useOn(new UseOnContext(actor,InteractionHand.MAIN_HAND,hit)).consumesAction()&&actor.containerMenu instanceof NativeGlassMenu,"sneaking Configurizer global dispatch");int window=actor.containerMenu.containerId;need(!NativeGlassMenu.apply(actor,new GlassSettingsPayload(BASE,window+1,0,0,1,-1,1,true,true,1,1)),"stale canonical window rejected");actor.closeContainer();
   var palette=new CompoundTag();palette.putString("Name","vandorlabs:programmable_glass");var state=NbtUtils.readBlockState(w.holderLookup(net.minecraft.core.registries.Registries.BLOCK),palette);need(state.getValue(NativeGlassBlock.SIZE)==1,"explicit previous palette absence default");w.setBlock(BASE.east(8),state,18);var legacy=(NativeGlassEntity)w.getBlockEntity(BASE.east(8));legacy.loadWithComponents(new CompoundTag(),w.registryAccess());legacy.refreshFluidGeometry();w.setBlock(BASE.east(16),b.defaultBlockState(),18);var recovery=(NativeGlassEntity)w.getBlockEntity(BASE.east(16));var bad=new CompoundTag();bad.putInt("NativeGlassSchema",99);bad.putByteArray("UnknownOwner",new byte[]{2,3,5,7});recovery.loadWithComponents(bad,w.registryAccess());saved(w);server.saveEverything(true,true,true);System.out.println("[vandorlabs][glass-canonical] write PASS checks="+checks);
  }catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][glass-canonical] FAIL "+failure);}finally{if(!reading)server.halt(false);}}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.LevelTickEvent.Post e){if(!reading||!(e.getLevel() instanceof ServerLevel w)||w!=w.getServer().overworld())return;try{need(++ticks<200,"restart preparation timeout");if(!(w.getBlockEntity(BASE) instanceof NativeGlassEntity)||!(w.getBlockEntity(BASE.east(8)) instanceof NativeGlassEntity legacy)||legacy.settings().glass().legacySize)return;saved(w);w.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][glass-canonical] read PASS checks="+checks);reading=false;w.getServer().halt(false);}catch(Throwable failure){failure.printStackTrace();reading=false;System.out.println("[vandorlabs][glass-canonical] FAIL "+failure);w.getServer().halt(false);}}
 private GlassCanonicalChecks(){}
}
